mapper.select:
SELECT product_id, total_quantity, available_quantity, reserved_quantity, sold_quantity, version, updated_at
FROM inventory
WHERE product_id = #{productId}

mapper.update:
UPDATE inventory
SET available_quantity = available_quantity - #{quantity},
    reserved_quantity = reserved_quantity + #{quantity},
    version = version + 1
WHERE product_id = #{productId}
  AND available_quantity >= #{quantity}

UPDATE inventory
SET reserved_quantity = reserved_quantity - #{quantity},
    sold_quantity = sold_quantity + #{quantity},
    version = version + 1
WHERE product_id = #{productId}
  AND reserved_quantity >= #{quantity}

UPDATE inventory
SET available_quantity = available_quantity + #{quantity},
    reserved_quantity = reserved_quantity - #{quantity},
    version = version + 1
WHERE product_id = #{productId}
  AND reserved_quantity >= #{quantity}

UPDATE inventory_reservation
SET status = 'CONFIRMED'
WHERE order_id = #{orderId}
  AND product_id = #{productId}
  AND status = 'TRY'

UPDATE inventory_reservation
SET status = 'CANCELLED'
WHERE order_id = #{orderId}
  AND product_id = #{productId}
  AND status = 'TRY'

UPDATE inventory_redis_sync
SET attempts = attempts + 1, last_error = #{error}
WHERE sync_id = #{syncId} AND applied_at IS NULL

mapper.select:
SELECT order_id, user_id, product_id, quantity, status, expires_at, created_at, updated_at
FROM inventory_reservation
WHERE status = 'TRY'
  AND expires_at <= #{now}
ORDER BY expires_at, order_id
LIMIT #{limit}
